package com.bank.index;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class EmployeeIndexDemo {
    private static final Logger log = Logger.getLogger("EmployeeIndex");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", 95000.0),
            new Employee(2L, "Priya", 250000.0),
            new Employee(2L, "Priya (corrected)", 260000.0) // duplicate id 2
        );
        EmployeeIndexService service = new EmployeeIndexService();
        Map<Long, Employee> index = service.indexById(staff);
        index.forEach((id, e) -> log.info(() -> id + " -> " + e.getName() + " (" + e.getSalary() + ")"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final double salary;
        Employee(Long id, String name, double salary) { this.id = id;
        this.name = name
        this.salary = salary; }
    Long getId() { return id; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/EmployeeIndexService.java ───
class EmployeeIndexService {
    // Merge on duplicate id: keep the higher-salary record (the corrected one).
    Map<Long, Employee> indexById(List<Employee> employees) {
        return employees.stream()
            .collect(toMap(
                Employee::getId,
                e -> e,
                (existing, replacement) ->
                    existing.getSalary() >= replacement.getSalary() ? existing : replacement));
    }
}
